code='''from collections import deque
def transform(grid):
    g=[row[:] for row in grid]; h=len(g); w=len(g[0]); c=9
    # Extend aligned marker runs between their endpoints to form the outline.
    for r in range(h):
        xs=[x for x in range(w) if g[r][x]==c]
        for x in range(min(xs,default=0),max(xs,default=-1)+1):
            if xs: g[r][x]=c
    for x in range(w):
        ys=[r for r in range(h) if g[r][x]==c]
        if ys:
            for r in range(min(ys),max(ys)+1): g[r][x]=c
    seen=set(); q=deque()
    for r in range(h):
        for x in range(w):
            if (r in (0,h-1) or x in (0,w-1)) and g[r][x]!=c:
                seen.add((r,x)); q.append((r,x))
    while q:
        r,x=q.popleft()
        for a,b in ((r-1,x),(r+1,x),(r,x-1),(r,x+1)):
            if 0<=a<h and 0<=b<w and g[a][b]!=c and (a,b) not in seen:
                seen.add((a,b)); q.append((a,b))
    for r in range(h):
        for x in range(w):
            if g[r][x]!=c and (r,x) not in seen: g[r][x]=2
    return g
'''
